function $(id){return document.getElementById(id);}

/* ---------- easing ---------- */
function cubic(x1,y1,x2,y2){
  var cx=3*x1,bx=3*(x2-x1)-cx,ax=1-cx-bx,cy=3*y1,by=3*(y2-y1)-cy,ay=1-cy-by;
  function sx(t){return((ax*t+bx)*t+cx)*t;}
