  function dx(t){return(3*ax*t+2*bx)*t+cx;}
  return function(u){
    if(u<=0)return 0;if(u>=1)return 1;
    var t=u,i,x,d;
    for(i=0;i<8;i++){x=sx(t)-u;if(Math.abs(x)<1e-6)return sy(t);d=dx(t);if(Math.abs(d)<1e-6)break;t-=x/d;}
    var lo=0,hi=1;t=u;
    while(lo<hi){x=sx(t);if(Math.abs(x-u)<1e-6)break;if(u>x)lo=t;else hi=t;t=(lo+hi)/2;if(hi-lo<1e-7)break;}
    return sy(t);
  };
