      if(v.kind==="color")val=String(S.inputs[v.name]);
      else if(v.kind==="boolean")val=S.inputs[v.name]?b.outMax:b.outMin;
      else{norm=(Number(S.inputs[v.name])-v.min)/((v.max-v.min)||1);norm=Math.max(0,Math.min(1,norm));val=b.outMin+(b.outMax-b.outMin)*norm;}
