function n(props,base,key){var v=props[key];if(typeof v==="number")return v;return typeof base[key]==="number"?base[key]:0;}
function s(props,base,key){var v=props[key];if(typeof v==="string"&&v)return v;return typeof base[key]==="string"?base[key]:"";}
function buildTransform(props,base){
