function applyElement(id,props){
  var geom=DATA.elements[id];
  if(!geom)return;
  var base=geom.base;
  if(geom.kind==="region"){
    var ro=$(P+"-ro-"+id);
    if(ro){
      var amount=n(props,base,"regionAmount")*n(props,base,"opacity");
      ro.setAttribute("opacity",String(Math.max(0,Math.min(1,amount))));
    }
    var rga=$(P+"-rga-"+id);
    if(rga&&props.glow!==undefined)rga.setAttribute("slope",String(2.4*n(props,base,"glow")));
