    sh.setAttribute("stroke-opacity",visible>0.01?String(base.strokeOpacity===undefined?1:base.strokeOpacity):"0");
    if(base.fill)sh.setAttribute("fill-opacity",String(Math.max(0,trimEnd-trimStart)));
  }
  if(props.glow!==undefined){
